local Camera = workspace.CurrentCamera
local TweenService = game:GetService("TweenService")
local module = {}
local OriginPositions = {}

function module.In(obj: GuiObject, tweenInfo: TweenInfo?, callback)
    if obj:IsA("GuiObject") then
        if not OriginPositions[obj] then
            OriginPositions[obj] = obj.Position
        end
        local screenSize = Camera.ViewportSize
        local screenY = screenSize.Y
        local fromPos = OriginPositions[obj] + UDim2.fromOffset(0, -screenY) 
        local targetPos = OriginPositions[obj]
        
        obj.Position = fromPos
        obj.Visible = true

        tweenInfo = tweenInfo or TweenInfo.new(.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        local anim = TweenService:Create(obj, tweenInfo, {Position = targetPos})
        anim.Completed:Connect(function(playBackState)
            if playBackState == Enum.PlaybackState.Completed then
                obj.Position = targetPos
                if callback then
                    callback()
                end
            end
        end)
        anim:Play()

        return {
            Cancel = function()
                anim:Cancel()
            end
        }
    end
end

function module.Out(obj: GuiObject, tweenInfo: TweenInfo?, callback)
    if obj:IsA("GuiObject") then
        if not OriginPositions[obj] then
            OriginPositions[obj] = obj.Position
        end
        local screenSize = Camera.ViewportSize
        local screenY = screenSize.Y
        local fromPos = OriginPositions[obj]
        local targetPos = OriginPositions[obj] + UDim2.fromOffset(0, -screenY)
        
        obj.Position = fromPos
        obj.Visible = true

        tweenInfo = tweenInfo or TweenInfo.new(.5, Enum.EasingStyle.Back, Enum.EasingDirection.In)
        local anim = TweenService:Create(obj, tweenInfo, {Position = targetPos})
        anim.Completed:Connect(function(playBackState)
            if playBackState == Enum.PlaybackState.Completed then
                obj.Visible = false
                obj.Position = fromPos
                if callback then
                    callback()
                end
            end
        end)
        anim:Play()

        return {
            Cancel = function()
                anim:Cancel()
            end
        }
    end
end

return module